const questionBank = {
  'bad-coding-practices': [
    { question: 'What is a "God Object" in object-oriented programming?', options: [{ label: 'A', text: 'An object that is perfectly designed and handles everything efficiently' }, { label: 'B', text: 'An object that knows too much or does too much, violating single responsibility' }, { label: 'C', text: 'An object used only by senior developers' }, { label: 'D', text: 'A singleton pattern implementation' }], correct: 'B', explanation: 'A God Object is an anti-pattern where a single class knows too much or does too much, violating the Single Responsibility Principle. It creates tight coupling and makes code hard to maintain.', difficulty: 'medium', tags: ['oop', 'anti-patterns'] },
    { question: 'What is "Magic Number" anti-pattern?', options: [{ label: 'A', text: 'Using random number generators in production code' }, { label: 'B', text: 'Using unnamed numeric constants directly in code without explanation' }, { label: 'C', text: 'Using prime numbers for hash functions' }, { label: 'D', text: 'Numbers used in encryption algorithms' }], correct: 'B', explanation: 'Magic numbers are unexplained numeric literals used directly in code. They make code hard to read and maintain. Use named constants instead, e.g., MAX_RETRIES = 3.', difficulty: 'easy', tags: ['readability', 'clean-code'] },
    { question: 'Which of the following is a classic example of "Spaghetti Code"?', options: [{ label: 'A', text: 'Code with clear module boundaries and single responsibilities' }, { label: 'B', text: 'Code with excessive use of GOTO statements and tangled control flow' }, { label: 'C', text: 'Code that uses Italian variable names' }, { label: 'D', text: 'Code that uses too many loops' }], correct: 'B', explanation: 'Spaghetti code refers to code with a complex and tangled control flow, often caused by excessive GOTO statements, deeply nested conditions, and lack of structured programming.', difficulty: 'easy', tags: ['code-quality'] },
    { question: 'What is "Copy-Paste Programming" and why is it harmful?', options: [{ label: 'A', text: 'A productivity technique; it is not harmful' }, { label: 'B', text: 'Duplicating code instead of abstracting it, leading to maintenance nightmares' }, { label: 'C', text: 'Copying code from open source projects' }, { label: 'D', text: 'Using templates to generate code' }], correct: 'B', explanation: 'Copy-paste programming leads to code duplication (DRY violation). When a bug is found in the original code, all copies must be updated manually — often missed, creating inconsistencies.', difficulty: 'easy', tags: ['dry', 'maintainability'] },
    { question: 'What does "Dead Code" refer to?', options: [{ label: 'A', text: 'Code that causes runtime crashes' }, { label: 'B', text: 'Code that is never executed during program run' }, { label: 'C', text: 'Code written by developers who have left the company' }, { label: 'D', text: 'Deprecated library functions' }], correct: 'B', explanation: 'Dead code is code that is never executed — unreachable branches, unused variables, or commented-out blocks. It adds confusion and noise without providing value. Remove it to keep the codebase clean.', difficulty: 'easy', tags: ['clean-code'] },
    { question: 'What is the "Premature Optimization" anti-pattern?', options: [{ label: 'A', text: 'Optimizing code after deployment' }, { label: 'B', text: 'Optimizing code before proving there is a performance problem, wasting effort' }, { label: 'C', text: 'Skipping code reviews for performance-critical modules' }, { label: 'D', text: 'Using caching everywhere by default' }], correct: 'B', explanation: '"Premature optimization is the root of all evil" — Donald Knuth. Optimizing before profiling leads to complex, unreadable code for gains that may never matter.', difficulty: 'medium', tags: ['performance', 'clean-code'] },
    { question: 'Which principle does "Long Method" smell violate?', options: [{ label: 'A', text: 'Open/Closed Principle' }, { label: 'B', text: 'Single Responsibility Principle' }, { label: 'C', text: 'Liskov Substitution Principle' }, { label: 'D', text: 'Interface Segregation Principle' }], correct: 'B', explanation: 'Long methods typically do too many things, violating the Single Responsibility Principle. Methods should be short, focused, and do one thing well.', difficulty: 'medium', tags: ['solid', 'refactoring'] },
    { question: 'What is a "Lava Flow" in software development?', options: [{ label: 'A', text: 'A deployment pipeline that overloads the server' }, { label: 'B', text: 'Dead code that cannot be removed because nobody understands what it does' }, { label: 'C', text: 'A cascading failure in microservices' }, { label: 'D', text: 'A hot-reload mechanism in web frameworks' }], correct: 'B', explanation: 'Lava flow refers to dead or outdated code that remains in a codebase because developers are afraid to touch it. Like cooled lava, it hardens in place and becomes immovable.', difficulty: 'hard', tags: ['technical-debt'] },
    { question: 'What problem does "Primitive Obsession" code smell cause?', options: [{ label: 'A', text: 'Using too many class hierarchies' }, { label: 'B', text: 'Overusing primitive data types instead of creating meaningful domain objects' }, { label: 'C', text: 'Using assembly-level primitives in high-level languages' }, { label: 'D', text: 'Excessive use of null values' }], correct: 'B', explanation: 'Primitive obsession means using primitives (int, string) where domain-specific types should be used. For example, using a string for email instead of an Email class with validation.', difficulty: 'hard', tags: ['oop', 'domain-modeling'] },
    { question: 'What is the main issue with "Feature Envy" code smell?', options: [{ label: 'A', text: 'A class that has too many features' }, { label: 'B', text: 'A method that accesses data of another class more than its own' }, { label: 'C', text: 'Developers wanting to add unnecessary features' }, { label: 'D', text: 'A class with too many public methods' }], correct: 'B', explanation: 'Feature envy occurs when a method seems more interested in a class other than the one it actually is in. This suggests the method should be moved to the class it envies.', difficulty: 'hard', tags: ['refactoring', 'oop'] },
    { question: 'What does the DRY principle stand for?', options: [{ label: 'A', text: 'Do Repeat Yourself' }, { label: 'B', text: 'Design, Refactor, Yield' }, { label: 'C', text: "Don't Repeat Yourself" }, { label: 'D', text: 'Develop, Review, Yield' }], correct: 'C', explanation: "DRY stands for Don't Repeat Yourself. Every piece of knowledge must have a single, unambiguous representation in the system. Duplication leads to maintenance problems and inconsistencies.", difficulty: 'easy', tags: ['principles', 'clean-code'] },
    { question: 'What is "Shotgun Surgery" code smell?', options: [{ label: 'A', text: 'When a single change requires making many small changes in many different classes' }, { label: 'B', text: 'Deleting large portions of code at once' }, { label: 'C', text: 'Making random changes and hoping they work' }, { label: 'D', text: 'Using too many design patterns' }], correct: 'A', explanation: 'Shotgun surgery happens when a single change requires many small changes scattered across many classes. This suggests poor encapsulation and the need for refactoring.', difficulty: 'medium', tags: ['refactoring', 'coupling'] },
    { question: 'Which of these is NOT a code smell?', options: [{ label: 'A', text: 'Long Parameter List' }, { label: 'B', text: 'Unit Testing' }, { label: 'C', text: 'Data Clumps' }, { label: 'D', text: 'Divergent Change' }], correct: 'B', explanation: 'Unit testing is a best practice, not a code smell. The others (Long Parameter List, Data Clumps, Divergent Change) are all recognized code smells that indicate refactoring opportunities.', difficulty: 'easy', tags: ['code-smells'] },
    { question: 'What is "Yo-yo problem" in OOP?', options: [{ label: 'A', text: 'When code performance oscillates between fast and slow' }, { label: 'B', text: 'Excessive use of inheritance making code hard to follow up and down the hierarchy' }, { label: 'C', text: 'When variables change values unpredictably' }, { label: 'D', text: 'Circular dependency between two modules' }], correct: 'B', explanation: 'The yo-yo problem occurs when a programmer has to keep jumping up and down a long inheritance hierarchy to understand a program. It indicates deep, unnecessary inheritance chains.', difficulty: 'hard', tags: ['inheritance', 'oop'] },
    { question: 'What is the ideal approach when you find duplicate code in a codebase?', options: [{ label: 'A', text: 'Leave it as-is to avoid breaking changes' }, { label: 'B', text: 'Extract the duplicated logic into a shared function or class' }, { label: 'C', text: 'Add comments explaining why it is duplicated' }, { label: 'D', text: 'Copy it to even more places for consistency' }], correct: 'B', explanation: 'Duplicate code should be extracted into a reusable abstraction — a function, method, or class. This follows the DRY principle and makes future changes easier and less error-prone.', difficulty: 'easy', tags: ['refactoring', 'dry'] },
  ],

  'security-vulnerabilities': [
    { question: 'What is SQL Injection and how is it prevented?', options: [{ label: 'A', text: 'A performance optimization; prevented by caching queries' }, { label: 'B', text: 'Inserting malicious SQL via user input; prevented by parameterized queries/prepared statements' }, { label: 'C', text: 'A type of database backup; prevented by encryption' }, { label: 'D', text: 'Slow SQL queries; prevented by indexing' }], correct: 'B', explanation: 'SQL Injection occurs when user input is embedded directly in SQL queries. Attackers inject malicious SQL to manipulate the database. Prevention: always use parameterized queries or ORMs that handle escaping.', difficulty: 'easy', tags: ['sql', 'injection', 'owasp'] },
    { question: 'What does XSS stand for and what does it allow an attacker to do?', options: [{ label: 'A', text: 'Extra Server Security; makes servers more secure' }, { label: 'B', text: 'Cross-Site Scripting; allows attackers to inject malicious scripts into web pages viewed by other users' }, { label: 'C', text: 'Cross-System Synchronization; syncs data across servers' }, { label: 'D', text: 'Extended Stylesheet Security; prevents CSS attacks' }], correct: 'B', explanation: 'XSS (Cross-Site Scripting) allows attackers to inject client-side scripts into web pages. The injected script runs in victims\' browsers and can steal cookies, session tokens, or perform actions on behalf of users.', difficulty: 'easy', tags: ['xss', 'owasp'] },
    { question: 'What is CSRF and what is the primary defense against it?', options: [{ label: 'A', text: 'Client-Side Request Forgery; prevent with HTTPS' }, { label: 'B', text: 'Cross-Site Request Forgery; prevent with CSRF tokens in forms' }, { label: 'C', text: 'Centralized Server Resource Framework; prevent with firewalls' }, { label: 'D', text: 'Cross-Server File Retrieval; prevent with authentication' }], correct: 'B', explanation: 'CSRF tricks authenticated users into submitting requests they did not intend. Defense: use CSRF tokens (unique, unpredictable values in forms) and SameSite cookie attribute.', difficulty: 'medium', tags: ['csrf', 'owasp'] },
    { question: 'What is the danger of storing passwords in plaintext?', options: [{ label: 'A', text: 'It is slower than hashed storage' }, { label: 'B', text: 'If the database is breached, all user passwords are immediately exposed' }, { label: 'C', text: 'It uses more disk space' }, { label: 'D', text: 'Plaintext passwords cannot be compared correctly' }], correct: 'B', explanation: 'Plaintext passwords expose all user accounts instantly if the database is compromised. Always hash passwords with a strong, slow algorithm like bcrypt, scrypt, or Argon2 — never MD5 or SHA1.', difficulty: 'easy', tags: ['authentication', 'passwords'] },
    { question: 'What is an Insecure Direct Object Reference (IDOR)?', options: [{ label: 'A', text: 'Using null pointers in object-oriented programming' }, { label: 'B', text: 'Exposing internal implementation objects via references that users can manipulate to access unauthorized data' }, { label: 'C', text: 'A type of memory leak in Java programs' }, { label: 'D', text: 'Using deprecated API endpoints' }], correct: 'B', explanation: 'IDOR occurs when a user can access or modify objects they should not by changing a reference (like a URL parameter: /api/invoices/1234). Always verify authorization for every resource access.', difficulty: 'medium', tags: ['authorization', 'owasp'] },
    { question: 'What is a security risk of using MD5 for password hashing?', options: [{ label: 'A', text: 'MD5 is too slow for login operations' }, { label: 'B', text: 'MD5 is cryptographically broken and fast to brute-force with rainbow tables' }, { label: 'C', text: 'MD5 produces hashes that are too long' }, { label: 'D', text: 'MD5 requires a salt by default' }], correct: 'B', explanation: 'MD5 is cryptographically broken, produces the same hash for the same input, and is extremely fast — allowing billions of guesses per second. Use bcrypt/Argon2 which are intentionally slow.', difficulty: 'medium', tags: ['cryptography', 'passwords'] },
    { question: 'What is a Man-in-the-Middle (MITM) attack?', options: [{ label: 'A', text: 'An attack by a developer who is "in the middle" of the team hierarchy' }, { label: 'B', text: 'An attacker secretly relays and possibly alters communications between two parties' }, { label: 'C', text: 'A database attack targeting middle tables in joins' }, { label: 'D', text: 'An attack on middleware software components' }], correct: 'B', explanation: 'MITM attacks intercept communication between two parties. The attacker can eavesdrop or alter data. Prevention: always use HTTPS/TLS, certificate pinning, and HSTS headers.', difficulty: 'medium', tags: ['network-security', 'tls'] },
    { question: 'What is "Security by Obscurity" and why is it considered poor practice?', options: [{ label: 'A', text: 'Using complex variable names to confuse attackers — an excellent security strategy' }, { label: 'B', text: 'Relying on secrecy of implementation rather than actual security mechanisms — fundamentally flawed' }, { label: 'C', text: 'Encrypting all source code before deployment' }, { label: 'D', text: 'Using dark web servers to host applications' }], correct: 'B', explanation: 'Security by obscurity relies on keeping system design secret rather than implementing real security. Once the secret is revealed, the system is completely vulnerable. Security should not depend on secrecy of design.', difficulty: 'medium', tags: ['security-principles'] },
    { question: 'What is the least privilege principle in security?', options: [{ label: 'A', text: 'Always give users admin access for convenience' }, { label: 'B', text: 'Every component should have only the minimum access rights it needs to function' }, { label: 'C', text: 'Denying all access to all users by default' }, { label: 'D', text: 'Giving different privileges to different programming languages' }], correct: 'B', explanation: 'The principle of least privilege states that users, processes, and systems should have only the minimum access necessary. This limits damage from breaches, bugs, or compromised accounts.', difficulty: 'easy', tags: ['access-control', 'principles'] },
    { question: 'What is a JWT (JSON Web Token) security concern?', options: [{ label: 'A', text: 'JWTs are too large for HTTP headers' }, { label: 'B', text: 'JWTs can be decoded by anyone; sensitive data must not be stored in the payload without encryption' }, { label: 'C', text: 'JWTs expire too quickly by default' }, { label: 'D', text: 'JWTs only work with SQL databases' }], correct: 'B', explanation: 'JWT payloads are base64 encoded, not encrypted — anyone can decode them. Never store sensitive data (passwords, SSNs) in JWT payloads. The signature only proves integrity, not confidentiality.', difficulty: 'hard', tags: ['jwt', 'authentication'] },
    { question: 'What is a "Zero-Day vulnerability"?', options: [{ label: 'A', text: 'A vulnerability patched on the same day it is discovered' }, { label: 'B', text: 'A newly discovered vulnerability that has no available patch; attackers can exploit it before developers respond' }, { label: 'C', text: 'A vulnerability that only exists for zero seconds' }, { label: 'D', text: 'A vulnerability introduced on day zero of a project' }], correct: 'B', explanation: 'A zero-day vulnerability is a flaw unknown to the software vendor, meaning "zero days" have passed since vendors became aware. Attackers exploit these before a patch exists.', difficulty: 'medium', tags: ['vulnerability-management'] },
    { question: 'Why is it dangerous to commit API keys or secrets to a Git repository?', options: [{ label: 'A', text: 'It slows down the repository' }, { label: 'B', text: 'Git history is permanent; even if deleted, secrets can be found in history by scanners or bad actors' }, { label: 'C', text: 'Git cannot store binary files like keys' }, { label: 'D', text: 'API keys get corrupted by Git compression' }], correct: 'B', explanation: 'Git history is immutable — even after deleting a commit, secrets remain in the history and can be extracted. Use environment variables and .env files (in .gitignore), and use tools like git-secrets.', difficulty: 'medium', tags: ['git', 'secrets-management'] },
    { question: 'What is "Broken Authentication" as per OWASP Top 10?', options: [{ label: 'A', text: 'A login page that looks visually broken' }, { label: 'B', text: 'Flaws in session management and authentication that allow attackers to impersonate users' }, { label: 'C', text: 'Authentication that requires too many steps' }, { label: 'D', text: 'Using deprecated authentication libraries' }], correct: 'B', explanation: 'Broken authentication includes weak passwords, missing MFA, session fixation, and improper session expiration. Attackers exploit these to compromise user accounts or escalate privileges.', difficulty: 'medium', tags: ['authentication', 'owasp'] },
    { question: 'What is Clickjacking?', options: [{ label: 'A', text: 'A technique to speed up mouse click response' }, { label: 'B', text: 'Tricking users into clicking a hidden element by overlaying a transparent iframe over a visible page' }, { label: 'C', text: 'A JavaScript performance optimization' }, { label: 'D', text: 'Hijacking JavaScript click event handlers' }], correct: 'B', explanation: 'Clickjacking overlays an invisible iframe over a legitimate page. Users think they click the visible content but are actually clicking the hidden malicious element. Prevention: use X-Frame-Options or CSP frame-ancestors header.', difficulty: 'hard', tags: ['ui-security', 'headers'] },
    { question: 'What is the recommended way to prevent XSS attacks?', options: [{ label: 'A', text: 'Use longer passwords for all users' }, { label: 'B', text: 'Validate and escape all user-supplied input before rendering it in the browser' }, { label: 'C', text: 'Use only POST requests instead of GET' }, { label: 'D', text: 'Disable JavaScript in the browser' }], correct: 'B', explanation: 'XSS prevention requires output encoding/escaping — converting characters like < > & into their HTML entities before rendering. Also use Content-Security-Policy headers and avoid innerHTML with user data.', difficulty: 'medium', tags: ['xss', 'input-validation'] },
  ],

  'software-testing': [
    { question: 'What is the main problem with writing no unit tests?', options: [{ label: 'A', text: 'The code runs slower' }, { label: 'B', text: 'Bugs are only caught in production, making them expensive and dangerous to fix' }, { label: 'C', text: 'The code cannot be compiled' }, { label: 'D', text: 'It violates the programming language license' }], correct: 'B', explanation: 'Without unit tests, bugs reach production where they affect real users and are expensive to diagnose. Tests provide a safety net for refactoring and a living specification of expected behavior.', difficulty: 'easy', tags: ['unit-testing', 'best-practices'] },
    { question: 'What is a "Flaky Test"?', options: [{ label: 'A', text: 'A test that is visually hard to read' }, { label: 'B', text: 'A test that passes and fails non-deterministically without code changes' }, { label: 'C', text: 'A test with too many assertions' }, { label: 'D', text: 'A test written in a dynamically typed language' }], correct: 'B', explanation: 'Flaky tests pass or fail randomly — they are unreliable. Causes include race conditions, time-dependent logic, or shared state between tests. Flaky tests erode trust in the test suite and mask real failures.', difficulty: 'medium', tags: ['test-quality', 'reliability'] },
    { question: 'What is the testing pyramid and what does it recommend?', options: [{ label: 'A', text: 'A hierarchy recommending more end-to-end tests than unit tests' }, { label: 'B', text: 'A hierarchy recommending many fast unit tests, fewer integration tests, and fewest E2E tests' }, { label: 'C', text: 'A pyramid-shaped UI test framework' }, { label: 'D', text: 'Testing code in decreasing order of complexity' }], correct: 'B', explanation: 'The testing pyramid (Mike Cohn) recommends: many cheap, fast unit tests at the base; fewer integration tests in the middle; and few expensive, slow E2E tests at the top. Inverting this (ice cream cone) is an anti-pattern.', difficulty: 'medium', tags: ['test-strategy', 'architecture'] },
    { question: 'What does code coverage measure and what is its limitation?', options: [{ label: 'A', text: 'It measures how many developers have read the code; limitation is subjectivity' }, { label: 'B', text: 'It measures percentage of code executed by tests; limitation: high coverage does not mean good tests' }, { label: 'C', text: 'It measures code performance; limitation is measurement overhead' }, { label: 'D', text: 'It measures documentation completeness; limitation is language support' }], correct: 'B', explanation: 'Code coverage measures how much code is exercised by tests. 100% coverage can still have poor tests with no meaningful assertions. Coverage is a useful metric but not a quality guarantee.', difficulty: 'medium', tags: ['code-coverage', 'metrics'] },
    { question: 'What is "Test-Driven Development" (TDD)?', options: [{ label: 'A', text: 'Writing all tests after completing the entire project' }, { label: 'B', text: 'Writing a failing test first, then writing code to make it pass, then refactoring' }, { label: 'C', text: 'Having a dedicated QA team drive development priorities' }, { label: 'D', text: 'Using only automated E2E tests to drive development' }], correct: 'B', explanation: 'TDD follows Red-Green-Refactor: write a failing test (red), write minimum code to pass it (green), refactor for quality. It leads to better design, higher coverage, and clearer requirements.', difficulty: 'medium', tags: ['tdd', 'methodology'] },
    { question: 'What is the problem with testing implementation details instead of behavior?', options: [{ label: 'A', text: 'It makes tests run faster than necessary' }, { label: 'B', text: 'Tests become brittle — breaking on refactoring even when behavior is correct' }, { label: 'C', text: 'It is only a problem in dynamically typed languages' }, { label: 'D', text: 'It requires more test data setup' }], correct: 'B', explanation: 'Tests tied to implementation details (e.g., private method names, internal state) break when you refactor, even if the observable behavior is unchanged. Test behavior/outcomes, not how the code achieves them.', difficulty: 'hard', tags: ['test-design', 'best-practices'] },
    { question: 'What is mocking and when is it misused?', options: [{ label: 'A', text: 'A UI library for animations; misused in production code' }, { label: 'B', text: 'Replacing real dependencies with controlled substitutes; misused when mocking everything including the system under test' }, { label: 'C', text: 'A testing tool for mobile apps; misused in web tests' }, { label: 'D', text: 'Using fake user data; misused with real emails' }], correct: 'B', explanation: 'Mocks replace dependencies for isolation. Over-mocking (mocking the class being tested, or mocking everything) leads to tests that do not actually verify anything meaningful and give false confidence.', difficulty: 'hard', tags: ['mocking', 'unit-testing'] },
    { question: 'What is Regression Testing?', options: [{ label: 'A', text: 'Testing that the software performs worse over time' }, { label: 'B', text: 'Testing to ensure previously working functionality still works after new changes' }, { label: 'C', text: 'Testing statistical regression models in code' }, { label: 'D', text: 'Going back to test older versions of the software' }], correct: 'B', explanation: 'Regression testing verifies that existing functionality was not broken by new code changes. Automated regression suites are essential for CI/CD pipelines to catch unintended breakage.', difficulty: 'easy', tags: ['regression', 'ci-cd'] },
    { question: 'What is a test "setup" (beforeEach/setUp) and why is excessive setup a smell?', options: [{ label: 'A', text: 'Code that configures hardware; excessive setup means poor hardware' }, { label: 'B', text: 'Code that runs before each test; excessive setup means tests are too complex or test too many things' }, { label: 'C', text: 'Database initialization scripts; excessive setup means too many tables' }, { label: 'D', text: 'Configuration files; excessive setup means poor DevOps' }], correct: 'B', explanation: 'beforeEach runs before every test to set up state. Very complex setups are a sign that the code under test has too many dependencies and the tests may be doing too much — a sign to refactor.', difficulty: 'medium', tags: ['test-design', 'code-smell'] },
    { question: 'What is "Happy Path Testing" malpractice?', options: [{ label: 'A', text: 'Only testing code that works correctly and ignoring edge cases and error paths' }, { label: 'B', text: 'Testing code in a positive and encouraging environment' }, { label: 'C', text: 'Testing UI components for visual appeal' }, { label: 'D', text: 'Testing with real production data that has no errors' }], correct: 'A', explanation: 'Testing only the happy path (successful scenarios) ignores error handling, edge cases, null inputs, and boundary conditions — exactly where most bugs hide in production.', difficulty: 'easy', tags: ['test-coverage', 'edge-cases'] },
    { question: 'Why should tests be independent of each other?', options: [{ label: 'A', text: 'Independent tests run in alphabetical order' }, { label: 'B', text: 'Tests that share state can fail for reasons unrelated to the code being tested, making debugging difficult' }, { label: 'C', text: 'Independence reduces the number of required tests' }, { label: 'D', text: 'Independent tests use less memory' }], correct: 'B', explanation: 'Test interdependence (test A leaving state that test B relies on) causes cascading failures and order-dependent test suites. Each test should set up its own state and clean up after itself.', difficulty: 'medium', tags: ['test-isolation', 'best-practices'] },
    { question: 'What is Integration Testing?', options: [{ label: 'A', text: 'Testing individual functions in isolation' }, { label: 'B', text: 'Testing how multiple components work together' }, { label: 'C', text: 'Testing user interface components' }, { label: 'D', text: 'Testing code after deployment to production' }], correct: 'B', explanation: 'Integration tests verify that multiple components, modules, or services work correctly together. They catch interface issues and data contract mismatches that unit tests cannot detect.', difficulty: 'easy', tags: ['integration-testing'] },
    { question: 'What is the purpose of a test fixture?', options: [{ label: 'A', text: 'A physical device for testing hardware components' }, { label: 'B', text: 'A fixed state of a set of objects used as a baseline for running tests' }, { label: 'C', text: 'A tool for measuring test performance' }, { label: 'D', text: 'A way to schedule automated tests' }], correct: 'B', explanation: 'A test fixture is a fixed baseline environment (data, state, objects) used to run tests consistently. It ensures tests run in a known, controlled context for reproducible results.', difficulty: 'medium', tags: ['test-infrastructure'] },
    { question: 'What is a smoke test in software testing?', options: [{ label: 'A', text: 'Testing if hardware emits smoke under load' }, { label: 'B', text: 'A quick, preliminary test to check if the most critical functionality works before deeper testing' }, { label: 'C', text: 'Testing code in a smoking room environment' }, { label: 'D', text: 'A performance test under extreme CPU load' }], correct: 'B', explanation: 'Smoke tests (or sanity tests) verify that the basic functionality works after a build. They catch major failures fast, preventing the team from wasting time on deeper testing of a broken build.', difficulty: 'medium', tags: ['test-types', 'ci-cd'] },
    { question: 'What is mutation testing?', options: [{ label: 'A', text: 'Testing code that modifies database records' }, { label: 'B', text: 'A technique that introduces small code changes (mutations) to verify that tests detect them' }, { label: 'C', text: 'Modifying test code to improve performance' }, { label: 'D', text: 'Testing genetic algorithm implementations' }], correct: 'B', explanation: 'Mutation testing evaluates test quality by introducing small bugs (mutations) into code and checking if tests fail. Tests that do not catch mutations are ineffective. It measures test effectiveness beyond code coverage.', difficulty: 'hard', tags: ['test-quality', 'advanced'] },
  ],

  'version-control': [
    { question: 'What is the danger of force-pushing to a shared branch?', options: [{ label: 'A', text: 'It uses more storage space' }, { label: 'B', text: 'It rewrites history, potentially deleting commits from other developers who have already pulled' }, { label: 'C', text: 'It slows down the repository' }, { label: 'D', text: 'It triggers the CI pipeline multiple times' }], correct: 'B', explanation: 'Force-pushing rewrites Git history. If teammates have pulled the branch, their local history diverges from the rewritten remote, causing confusion and potential data loss. Never force-push to shared branches.', difficulty: 'medium', tags: ['git', 'collaboration'] },
    { question: 'What is "committing directly to main/master" considered bad practice?', options: [{ label: 'A', text: 'It is a best practice for solo projects only' }, { label: 'B', text: 'Direct commits bypass code review, CI checks, and conflict resolution processes' }, { label: 'C', text: 'It is bad only because main has more storage' }, { label: 'D', text: 'Direct commits are slower than pull requests' }], correct: 'B', explanation: 'Direct commits to main bypass code review, automated tests, and team visibility. Use feature branches and pull/merge requests to ensure quality gates and knowledge sharing.', difficulty: 'easy', tags: ['branching', 'workflow'] },
    { question: 'Why are meaningful commit messages important?', options: [{ label: 'A', text: 'They are not important; code is self-explanatory' }, { label: 'B', text: 'They make git log, blame, and bisect useful for understanding changes and tracking bugs' }, { label: 'C', text: 'Longer messages improve repository performance' }, { label: 'D', text: 'They are required by all Git hosting providers' }], correct: 'B', explanation: '"Fixed bug" or "WIP" are meaningless in history. Good messages explain WHAT changed and WHY, making `git log`, `git blame`, and `git bisect` invaluable for debugging and code review.', difficulty: 'easy', tags: ['commit-messages', 'best-practices'] },
    { question: 'What is the purpose of a .gitignore file?', options: [{ label: 'A', text: 'To list developers who should be ignored during code review' }, { label: 'B', text: 'To specify intentionally untracked files Git should ignore (e.g., build artifacts, secrets, node_modules)' }, { label: 'C', text: 'To disable certain Git commands' }, { label: 'D', text: 'To ignore merge conflicts automatically' }], correct: 'B', explanation: '.gitignore prevents sensitive files (API keys, .env), build artifacts (dist/, node_modules/), and IDE-specific files from being tracked. Committing these clutters history and can expose secrets.', difficulty: 'easy', tags: ['git', 'setup'] },
    { question: 'What is "Git rebase" and when should you avoid it?', options: [{ label: 'A', text: 'A way to rename branches; avoid on large repositories' }, { label: 'B', text: 'Replaying commits on a new base; avoid on shared/public branches as it rewrites history' }, { label: 'C', text: 'Reverting commits; avoid when commits are old' }, { label: 'D', text: 'Merging branches; avoid for small features' }], correct: 'B', explanation: 'Rebase replays commits on top of another branch, creating a linear history. Never rebase commits already pushed to shared branches — it rewrites history and causes problems for collaborators.', difficulty: 'hard', tags: ['git-rebase', 'workflow'] },
    { question: 'What is a merge conflict and what causes it?', options: [{ label: 'A', text: 'A conflict between frontend and backend developers' }, { label: 'B', text: 'When two branches have made changes to the same part of a file and Git cannot auto-merge them' }, { label: 'C', text: 'When the merge command is run incorrectly' }, { label: 'D', text: 'When the repository is too large to merge' }], correct: 'B', explanation: 'Merge conflicts occur when two branches modify the same lines of a file differently. Git cannot determine which change to keep, requiring manual resolution. Frequent small merges reduce conflict severity.', difficulty: 'easy', tags: ['merge', 'collaboration'] },
    { question: 'What is the recommended Git branching strategy for teams?', options: [{ label: 'A', text: 'Everyone works on the main branch for maximum collaboration' }, { label: 'B', text: 'Use feature branches (Gitflow, GitHub Flow) with pull requests for code review before merging' }, { label: 'C', text: 'Use one branch per developer for their entire career' }, { label: 'D', text: 'Use a different repository for each feature' }], correct: 'B', explanation: 'Feature branches isolate work, allow parallel development, enable code review via pull requests, and keep main branch stable. Gitflow and GitHub Flow are popular branching strategies.', difficulty: 'medium', tags: ['branching-strategy', 'workflow'] },
    { question: 'What does "git stash" do and when is it useful?', options: [{ label: 'A', text: 'Permanently deletes uncommitted changes' }, { label: 'B', text: 'Temporarily shelves uncommitted changes so you can switch branches without losing work' }, { label: 'C', text: 'Archives old branches to free up space' }, { label: 'D', text: 'Compresses the repository for faster cloning' }], correct: 'B', explanation: 'git stash saves your uncommitted changes (tracked files) onto a stack, giving you a clean working directory. You can stash, switch branches, do work, then `git stash pop` to restore your changes.', difficulty: 'medium', tags: ['git-stash', 'workflow'] },
    { question: 'What is the danger of a very large, long-lived feature branch?', options: [{ label: 'A', text: 'Large branches use more disk space' }, { label: 'B', text: 'It drifts far from the main branch, causing massive merge conflicts and integration problems' }, { label: 'C', text: 'Large branches cannot be deleted' }, { label: 'D', text: 'It slows down the Git hosting server' }], correct: 'B', explanation: 'Long-lived branches accumulate divergence from main. When finally merged, the conflicts are massive and integration issues are numerous. Prefer small, short-lived branches that merge frequently.', difficulty: 'medium', tags: ['branching', 'merge-strategy'] },
    { question: 'What is "git cherry-pick" used for?', options: [{ label: 'A', text: 'Selecting the best commit messages from the team' }, { label: 'B', text: 'Applying the changes from a specific commit onto another branch without merging the entire branch' }, { label: 'C', text: 'Deleting commits that are considered bad' }, { label: 'D', text: 'Filtering large files from the repository' }], correct: 'B', explanation: 'Cherry-pick applies the changes from one specific commit to your current branch. Useful for backporting a bug fix to a release branch without merging all new feature commits.', difficulty: 'hard', tags: ['git-cherry-pick', 'workflow'] },
    { question: 'What is the best practice for handling environment-specific configuration in a repository?', options: [{ label: 'A', text: 'Hardcode all configuration values directly in the code' }, { label: 'B', text: 'Use a .env.example file in the repo and keep actual .env files in .gitignore' }, { label: 'C', text: 'Create a separate branch for each environment' }, { label: 'D', text: 'Store all configs in a README file' }], correct: 'B', explanation: 'Commit .env.example (with placeholder values) to show required variables, but keep actual .env files (with real secrets) in .gitignore. Never commit real credentials to version control.', difficulty: 'easy', tags: ['configuration', 'secrets'] },
    { question: 'What does "git bisect" help you do?', options: [{ label: 'A', text: 'Split a repository into two equal halves' }, { label: 'B', text: 'Use binary search through commit history to find the commit that introduced a bug' }, { label: 'C', text: 'Divide branches evenly among team members' }, { label: 'D', text: 'Create two parallel versions of the codebase' }], correct: 'B', explanation: 'git bisect uses binary search to efficiently find the commit that introduced a bug. You mark commits as "good" or "bad" and Git checks out the midpoint until it narrows down to the culprit commit.', difficulty: 'hard', tags: ['debugging', 'git-bisect'] },
    { question: 'Why should commits be small and focused on a single change?', options: [{ label: 'A', text: 'Git has a file size limit per commit' }, { label: 'B', text: 'Small commits are easier to review, revert, and understand in history — large commits mix concerns' }, { label: 'C', text: 'Small commits run the CI pipeline faster' }, { label: 'D', text: 'Git requires commits to be under 100 lines' }], correct: 'B', explanation: 'A commit should represent one logical change. Large commits that mix features, bugs, and refactoring are hard to review, impossible to revert cleanly, and make git log nearly useless for history analysis.', difficulty: 'easy', tags: ['commit-strategy', 'best-practices'] },
    { question: 'What is a Pull Request (PR) / Merge Request (MR)?', options: [{ label: 'A', text: 'A request to pull code from a junior developer to a senior' }, { label: 'B', text: 'A formal proposal to merge a feature branch into another branch, enabling code review and discussion' }, { label: 'C', text: 'A request for the CI server to pull code from Git' }, { label: 'D', text: 'Pulling changes from a remote repository' }], correct: 'B', explanation: 'A PR/MR is a mechanism for code review — a developer proposes changes, reviewers provide feedback, automated checks run, and changes are merged only after approval. It is the cornerstone of team code quality.', difficulty: 'easy', tags: ['code-review', 'workflow'] },
    { question: 'What is "rebasing vs merging" — what is the key trade-off?', options: [{ label: 'A', text: 'Merging is faster; rebasing uses more CPU' }, { label: 'B', text: 'Rebase creates linear history but rewrites commits; merge preserves history but adds merge commits' }, { label: 'C', text: 'Rebasing only works with GitHub; merging works everywhere' }, { label: 'D', text: 'Merging requires more disk space; rebasing saves space' }], correct: 'B', explanation: 'Merging preserves true history with merge commits. Rebasing creates a cleaner linear history but rewrites SHA hashes. The choice depends on team workflow — rebase for local cleanup, merge for shared history.', difficulty: 'hard', tags: ['merge', 'rebase'] },
  ],

  'database-design': [
    { question: 'What is database normalization and why is it important?', options: [{ label: 'A', text: 'Normalizing database performance metrics' }, { label: 'B', text: 'Organizing data to reduce redundancy and improve integrity by eliminating update anomalies' }, { label: 'C', text: 'Converting a SQL database to NoSQL' }, { label: 'D', text: 'Backing up data in normal operating conditions' }], correct: 'B', explanation: 'Normalization organizes tables to reduce data redundancy. Unnormalized data leads to update anomalies — changing one piece of data requires multiple updates, causing inconsistency if any update fails.', difficulty: 'medium', tags: ['normalization', 'data-modeling'] },
    { question: 'What is the N+1 query problem?', options: [{ label: 'A', text: 'Executing N database tables with only one connection' }, { label: 'B', text: 'Fetching a list of N items then making N additional queries to fetch related data for each item' }, { label: 'C', text: 'A database that can only handle N+1 connections' }, { label: 'D', text: 'Using N+1 as a magic constant in SQL queries' }], correct: 'B', explanation: 'N+1 occurs when you fetch N records and then make one additional query per record. For 100 posts + 100 author queries = 101 queries. Fix with JOIN queries or eager loading (include/populate).', difficulty: 'medium', tags: ['orm', 'performance', 'queries'] },
    { question: 'What is a database index and when can it hurt performance?', options: [{ label: 'A', text: 'A list of table names; it never hurts performance' }, { label: 'B', text: 'A data structure speeding up reads; too many indexes slow down writes and consume storage' }, { label: 'C', text: 'A backup of the database; it hurts when storage is full' }, { label: 'D', text: 'A list of all queries; it hurts when queries are complex' }], correct: 'B', explanation: 'Indexes speed up SELECT queries by avoiding full table scans. However, every index must be updated on INSERT/UPDATE/DELETE. Over-indexing wastes storage and slows write operations significantly.', difficulty: 'medium', tags: ['indexing', 'performance'] },
    { question: 'What is a "Foreign Key" and what problem does it prevent?', options: [{ label: 'A', text: 'An encryption key stored in a foreign country; prevents data theft' }, { label: 'B', text: 'A column referencing a primary key in another table; prevents orphaned records and ensures referential integrity' }, { label: 'C', text: 'A key used by foreign developers; prevents naming conflicts' }, { label: 'D', text: 'An alternative primary key; prevents duplicate primary keys' }], correct: 'B', explanation: 'Foreign keys enforce referential integrity — you cannot have an order referencing a customer that does not exist. Without them, orphaned records (referencing deleted parents) corrupt data consistency.', difficulty: 'easy', tags: ['relational-db', 'integrity'] },
    { question: 'What is the danger of storing all data in a single, flat table?', options: [{ label: 'A', text: 'Flat tables cannot be indexed' }, { label: 'B', text: 'Massive data duplication, update anomalies, and inability to represent relationships accurately' }, { label: 'C', text: 'Single tables are limited to 100 rows' }, { label: 'D', text: 'Flat tables do not support primary keys' }], correct: 'B', explanation: 'Flat tables repeat data (e.g., customer name in every order row). Updating the customer name requires changing every order row — miss one and data is inconsistent. Normalization solves this through table relationships.', difficulty: 'medium', tags: ['normalization', 'data-modeling'] },
    { question: 'What is a database transaction and what does ACID stand for?', options: [{ label: 'A', text: 'A financial transaction; Automated, Confirmed, Integrated, Documented' }, { label: 'B', text: 'A unit of work; Atomicity, Consistency, Isolation, Durability' }, { label: 'C', text: 'A stored procedure; Asynchronous, Cached, Indexed, Deployed' }, { label: 'D', text: 'A query batch; Accurate, Complete, Independent, Dynamic' }], correct: 'B', explanation: 'ACID properties ensure reliable database transactions: Atomicity (all-or-nothing), Consistency (data remains valid), Isolation (transactions do not interfere), Durability (committed data persists).', difficulty: 'hard', tags: ['transactions', 'acid'] },
    { question: 'What is "SELECT *" and why is it considered bad practice in production queries?', options: [{ label: 'A', text: 'Selecting deleted records; returns corrupted data' }, { label: 'B', text: 'Fetching all columns when only a few are needed wastes memory, bandwidth, and can break code when schema changes' }, { label: 'C', text: 'It selects all databases on the server simultaneously' }, { label: 'D', text: 'SELECT * is bad only in NoSQL databases' }], correct: 'B', explanation: 'SELECT * retrieves all columns — even unused ones — wasting I/O, memory, and network bandwidth. It also breaks code when columns are added or removed. Always specify only the columns you need.', difficulty: 'easy', tags: ['sql', 'performance', 'best-practices'] },
    { question: 'What is a "Database Connection Pool" and why is it needed?', options: [{ label: 'A', text: 'A swimming pool metaphor for database team organization' }, { label: 'B', text: 'A cache of reusable database connections to avoid the overhead of creating a new connection per request' }, { label: 'C', text: 'A backup database for disaster recovery' }, { label: 'D', text: 'A distributed database across multiple servers' }], correct: 'B', explanation: 'Creating a database connection is expensive (network handshake, authentication). Connection pools maintain a set of open connections that are reused across requests, significantly improving performance under load.', difficulty: 'hard', tags: ['performance', 'connections'] },
    { question: 'What is NoSQL and when should you choose it over SQL?', options: [{ label: 'A', text: 'A programming language that avoids SQL; always choose it over SQL' }, { label: 'B', text: 'Non-relational databases; choose for flexible schema, high-volume write-heavy workloads, or document/graph data' }, { label: 'C', text: 'A type of database that does not use the word SQL' }, { label: 'D', text: 'A backup storage system; choose when SQL is down' }], correct: 'B', explanation: 'NoSQL databases (MongoDB, Redis, Cassandra) offer flexible schemas, horizontal scaling, and specialized data models. Choose based on data shape: documents for JSON-like data, graph for relationships, time-series for metrics.', difficulty: 'medium', tags: ['nosql', 'database-selection'] },
    { question: 'What is the danger of not validating data before inserting into a database?', options: [{ label: 'A', text: 'Invalid data causes slower queries' }, { label: 'B', text: 'Invalid, corrupt, or malicious data enters the database, causing application errors or security vulnerabilities' }, { label: 'C', text: 'Unvalidated data uses more storage' }, { label: 'D', text: 'The database will reject all invalid data automatically' }], correct: 'B', explanation: 'Without validation, bad data enters the database: negative prices, invalid emails, SQL injection payloads, or null required fields. Validate at the application layer AND enforce constraints at the database level.', difficulty: 'easy', tags: ['validation', 'data-integrity'] },
    { question: 'What is Database Sharding?', options: [{ label: 'A', text: 'Backing up the database in small fragments' }, { label: 'B', text: 'Horizontally partitioning data across multiple database instances to distribute load' }, { label: 'C', text: 'Breaking database tables into smaller columns' }, { label: 'D', text: 'Deleting old database records to free space' }], correct: 'B', explanation: 'Sharding distributes data across multiple servers (e.g., users A-M on server 1, N-Z on server 2). It enables horizontal scaling but adds complexity in queries that need data from multiple shards.', difficulty: 'hard', tags: ['scalability', 'sharding'] },
    { question: 'What is an ORM and what is its main drawback?', options: [{ label: 'A', text: 'Object Relational Mapping; maps database tables to objects in code; drawback: can generate inefficient queries' }, { label: 'B', text: 'Object Runtime Manager; manages object lifecycle; drawback: requires Java' }, { label: 'C', text: 'Open Relational Model; a database standard; drawback: limited language support' }, { label: 'D', text: 'Optimized Request Manager; handles HTTP; drawback: not suitable for REST APIs' }], correct: 'A', explanation: 'ORMs (Mongoose, Sequelize, SQLAlchemy) map database tables to code objects, increasing developer productivity. Drawback: they can generate inefficient SQL (e.g., N+1 queries) if not used carefully.', difficulty: 'medium', tags: ['orm', 'tools'] },
    { question: 'What is a "Stored Procedure" and what is a risk of overusing them?', options: [{ label: 'A', text: 'A saved SQL file; risk is disk space usage' }, { label: 'B', text: 'Pre-compiled SQL logic stored in the database; risk: business logic in the DB layer makes code harder to test, version, and deploy' }, { label: 'C', text: 'An encrypted database backup; risk is data exposure' }, { label: 'D', text: 'A database user account; risk is unauthorized access' }], correct: 'B', explanation: 'Stored procedures run server-side SQL logic. Overusing them puts business logic in the database, making it hard to version control, test independently, or migrate to a different database engine.', difficulty: 'hard', tags: ['stored-procedures', 'architecture'] },
    { question: 'What is database migration and why is it important in team projects?', options: [{ label: 'A', text: 'Moving a database to a new country' }, { label: 'B', text: 'Version-controlled scripts that evolve the database schema alongside application code' }, { label: 'C', text: 'Migrating data between SQL and NoSQL' }, { label: 'D', text: 'Backing up the database before updates' }], correct: 'B', explanation: 'Migrations are versioned scripts (e.g., using Flyway, Liquibase, or Knex) that track schema changes. They ensure all team members and environments (dev, staging, prod) have the same database structure.', difficulty: 'medium', tags: ['migrations', 'devops'] },
    { question: 'What is a race condition in the context of databases?', options: [{ label: 'A', text: 'Two SQL queries competing for the fastest execution time' }, { label: 'B', text: 'When two concurrent transactions read and modify the same data, causing inconsistency depending on execution order' }, { label: 'C', text: 'A performance benchmark test for databases' }, { label: 'D', text: 'A database query that times out due to race conditions in network' }], correct: 'B', explanation: 'Race conditions occur when concurrent transactions read-then-write the same data. Two users booking the last concert ticket simultaneously both see 1 ticket available and both succeed — overselling. Solution: locking, transactions with proper isolation levels.', difficulty: 'hard', tags: ['concurrency', 'transactions'] },
  ],

  'api-design': [
    { question: 'What HTTP status code should a successful resource creation return?', options: [{ label: 'A', text: '200 OK' }, { label: 'B', text: '201 Created' }, { label: 'C', text: '204 No Content' }, { label: 'D', text: '202 Accepted' }], correct: 'B', explanation: '201 Created is the correct response for a successful POST that creates a resource. The response should include a Location header pointing to the new resource URL and/or the resource in the body.', difficulty: 'easy', tags: ['rest', 'http-status'] },
    { question: 'What is the difference between PUT and PATCH in REST APIs?', options: [{ label: 'A', text: 'PUT is for databases; PATCH is for files' }, { label: 'B', text: 'PUT replaces the entire resource; PATCH applies a partial update to specific fields' }, { label: 'C', text: 'PUT is faster; PATCH is more secure' }, { label: 'D', text: 'PUT is deprecated; PATCH is the modern standard' }], correct: 'B', explanation: 'PUT is idempotent and replaces the complete resource (you must send all fields). PATCH updates only the provided fields. Use PATCH for partial updates to avoid accidentally nullifying unmentioned fields.', difficulty: 'medium', tags: ['rest', 'http-methods'] },
    { question: 'What is the problem with returning 200 OK for error responses?', options: [{ label: 'A', text: 'It wastes bandwidth' }, { label: 'B', text: 'Clients and monitoring tools cannot distinguish success from failure, masking errors' }, { label: 'C', text: '200 is only valid for GET requests' }, { label: 'D', text: 'It causes the browser to cache error responses' }], correct: 'B', explanation: 'Returning 200 with an error body is deceptive — HTTP clients, proxies, load balancers, and monitoring tools all use status codes to detect failures. Always return appropriate error codes (400, 404, 422, 500).', difficulty: 'easy', tags: ['rest', 'error-handling'] },
    { question: 'What is API Versioning and why is it necessary?', options: [{ label: 'A', text: 'Keeping track of how many API calls were made' }, { label: 'B', text: 'Providing multiple API versions simultaneously so existing clients are not broken by new changes' }, { label: 'C', text: 'Versioning the programming language the API is written in' }, { label: 'D', text: 'Creating a new server for every API update' }], correct: 'B', explanation: 'API versioning (via URL path /v1/ /v2/ or headers) allows introducing breaking changes without breaking existing clients. Without versioning, any change to the API can break all dependent applications.', difficulty: 'medium', tags: ['api-versioning', 'breaking-changes'] },
    { question: 'What is the danger of exposing internal database IDs (auto-increment integers) in a public API?', options: [{ label: 'A', text: 'Integer IDs are slower to process than strings' }, { label: 'B', text: 'They reveal record counts, enable enumeration attacks, and expose internal database structure' }, { label: 'C', text: 'Internal IDs cannot be serialized to JSON' }, { label: 'D', text: 'Integer IDs are too short for modern applications' }], correct: 'B', explanation: 'Sequential IDs reveal business intelligence (user #1000 means ~1000 users) and enable IDOR attacks (/users/1, /users/2). Use UUIDs or opaque random identifiers for public-facing APIs.', difficulty: 'hard', tags: ['security', 'rest'] },
    { question: 'What is rate limiting in APIs and why is it important?', options: [{ label: 'A', text: 'Limiting how fast developers can write API code' }, { label: 'B', text: 'Restricting the number of requests a client can make in a time window to prevent abuse and ensure fair usage' }, { label: 'C', text: 'Limiting the size of API responses' }, { label: 'D', text: 'Controlling the speed of the database queries' }], correct: 'B', explanation: 'Rate limiting prevents API abuse, DDoS attacks, and resource exhaustion. Return 429 Too Many Requests when limits are exceeded. Include Retry-After headers to tell clients when to retry.', difficulty: 'medium', tags: ['rate-limiting', 'security'] },
    { question: 'What is CORS and why do APIs need to configure it?', options: [{ label: 'A', text: 'A caching strategy; APIs need it for performance' }, { label: 'B', text: 'Cross-Origin Resource Sharing; browser security policy that APIs must configure to allow requests from different domains' }, { label: 'C', text: 'A compression algorithm; APIs use it to reduce response size' }, { label: 'D', text: 'A routing protocol; APIs configure it for load balancing' }], correct: 'B', explanation: "CORS is a browser security policy preventing JavaScript from making requests to different domains. APIs must include CORS headers (Access-Control-Allow-Origin) to allow legitimate cross-origin requests from approved domains.", difficulty: 'medium', tags: ['cors', 'security'] },
    { question: 'What is the ideal response structure for a REST API error?', options: [{ label: 'A', text: 'Return an empty response with just the HTTP status code' }, { label: 'B', text: 'Return a JSON object with error code, message, and optionally field-level details' }, { label: 'C', text: 'Return HTML with a detailed error page' }, { label: 'D', text: 'Return the full stack trace for debugging' }], correct: 'B', explanation: 'Good error responses include: HTTP status code, machine-readable error code, human-readable message, and optional field errors. Never return stack traces to clients in production — they expose internal implementation.', difficulty: 'medium', tags: ['error-handling', 'best-practices'] },
    { question: 'What is GraphQL and what problem does it solve compared to REST?', options: [{ label: 'A', text: 'A graph database; solves non-relational data problems' }, { label: 'B', text: 'A query language for APIs; solves over-fetching and under-fetching by letting clients request exactly the data they need' }, { label: 'C', text: 'A graphical REST client; solves documentation problems' }, { label: 'D', text: 'A caching layer for REST APIs; solves performance problems' }], correct: 'B', explanation: 'GraphQL allows clients to specify exactly what data they need in a single request. REST over-fetches (extra fields) or under-fetches (multiple round-trips needed). GraphQL eliminates both with a flexible query language.', difficulty: 'hard', tags: ['graphql', 'api-design'] },
    { question: 'What is Idempotency in the context of HTTP methods?', options: [{ label: 'A', text: 'An API that always returns the same response regardless of input' }, { label: 'B', text: 'Making the same request multiple times produces the same result as making it once' }, { label: 'C', text: 'An API that caches all responses permanently' }, { label: 'D', text: 'A method that can only be called during business hours' }], correct: 'B', explanation: 'Idempotent requests (GET, PUT, DELETE) can be safely retried — multiple identical calls have the same effect as one. POST is not idempotent (calling it twice creates two resources). Design for idempotency to handle retries safely.', difficulty: 'hard', tags: ['idempotency', 'rest'] },
    { question: 'What is the purpose of pagination in API design?', options: [{ label: 'A', text: 'Breaking responses into multiple API versions' }, { label: 'B', text: 'Returning data in chunks to prevent overwhelming clients and servers with huge datasets' }, { label: 'C', text: 'Adding page numbers to API documentation' }, { label: 'D', text: 'Encrypting API responses in multiple layers' }], correct: 'B', explanation: 'Returning all records at once (/users returning 10 million users) will crash clients and servers. Pagination (offset/limit or cursor-based) returns manageable chunks, improving performance and user experience.', difficulty: 'easy', tags: ['pagination', 'performance'] },
    { question: 'What is API documentation and what tool is commonly used for REST APIs?', options: [{ label: 'A', text: 'Comments in source code; JSDoc is commonly used' }, { label: 'B', text: 'Structured documentation of endpoints, parameters, and responses; Swagger/OpenAPI is commonly used' }, { label: 'C', text: 'README files; Markdown is the common tool' }, { label: 'D', text: 'Database schema diagrams; ERD tools are commonly used' }], correct: 'B', explanation: 'API documentation (Swagger/OpenAPI) describes endpoints, request/response schemas, authentication, and examples. Good docs reduce integration friction and are often auto-generated from code annotations.', difficulty: 'easy', tags: ['documentation', 'swagger'] },
    { question: 'What is the difference between authentication and authorization?', options: [{ label: 'A', text: 'Authentication controls access; authorization verifies identity — they are the same' }, { label: 'B', text: 'Authentication verifies WHO you are; authorization determines WHAT you are allowed to do' }, { label: 'C', text: 'Authentication is for APIs; authorization is for databases' }, { label: 'D', text: 'Authentication uses tokens; authorization uses passwords' }], correct: 'B', explanation: 'Authentication: "Who are you?" (login/JWT verification). Authorization: "What can you do?" (role checks, permission scopes). Confusing them leads to security bugs where authenticated users access unauthorized resources.', difficulty: 'medium', tags: ['auth', 'security'] },
    { question: 'What is an API Gateway and what are its benefits?', options: [{ label: 'A', text: 'A physical server that hosts API code' }, { label: 'B', text: 'A single entry point for multiple backend services that handles routing, auth, rate limiting, and monitoring' }, { label: 'C', text: 'A tool for testing APIs locally' }, { label: 'D', text: 'An API documentation hosting service' }], correct: 'B', explanation: 'An API Gateway (Kong, AWS API Gateway) sits in front of microservices and handles cross-cutting concerns: authentication, rate limiting, caching, logging, and routing — so individual services do not need to implement these.', difficulty: 'hard', tags: ['microservices', 'gateway'] },
    { question: 'What is Webhook and how does it differ from polling?', options: [{ label: 'A', text: 'A web-based hookah; differs from polling in cultural context' }, { label: 'B', text: 'A server-to-server callback when an event occurs; polling repeatedly asks for updates — webhooks push updates only when they happen' }, { label: 'C', text: 'A type of HTML hook; differs from polling in browser support' }, { label: 'D', text: 'An API authentication method; differs from polling in security level' }], correct: 'B', explanation: 'Polling: client repeatedly asks "anything new?" — wasteful. Webhooks: server calls YOUR endpoint when something happens — efficient, real-time. Used by Stripe, GitHub, Twilio for event notifications.', difficulty: 'medium', tags: ['webhooks', 'events'] },
  ],

  'debugging-errors': [
    { question: 'What is a "Silent Failure" and why is it dangerous?', options: [{ label: 'A', text: 'A crash that does not make noise' }, { label: 'B', text: 'An error that is swallowed or ignored, causing the program to continue in an incorrect state without any indication' }, { label: 'C', text: 'A failure that occurs outside of business hours' }, { label: 'D', text: 'An error in logging that fails silently' }], correct: 'B', explanation: 'Silent failures occur when exceptions are caught and discarded (empty catch blocks). The program continues as if everything is fine while operating on corrupted state, making bugs nearly impossible to trace.', difficulty: 'medium', tags: ['error-handling', 'debugging'] },
    { question: 'What is the issue with a bare "catch(e) {}" (empty catch block)?', options: [{ label: 'A', text: 'It causes syntax errors in some languages' }, { label: 'B', text: 'Exceptions are silently swallowed, hiding errors that could indicate serious problems' }, { label: 'C', text: 'Empty catch blocks increase memory usage' }, { label: 'D', text: 'It is only an issue in dynamically typed languages' }], correct: 'B', explanation: 'An empty catch block is one of the most dangerous patterns — it says "something went wrong, but I do not care." At minimum, log the error. Better: handle it appropriately or let it propagate to a proper error handler.', difficulty: 'easy', tags: ['exception-handling', 'anti-patterns'] },
    { question: 'What is structured logging and why is it preferred over plain text logs?', options: [{ label: 'A', text: 'Logging in JSON or key-value format; preferred because it can be easily queried, filtered, and analyzed by log aggregation tools' }, { label: 'B', text: 'Organizing log files in folders; preferred for disk space management' }, { label: 'C', text: 'Logging only error-level messages; preferred for performance' }, { label: 'D', text: 'Using colored console output; preferred for readability' }], correct: 'A', explanation: 'Structured logs (JSON) have fields like timestamp, level, message, userId, requestId. Tools like Elasticsearch, Splunk, or Datadog can search and aggregate these. Plain text is hard to parse at scale.', difficulty: 'hard', tags: ['logging', 'observability'] },
    { question: 'What is a Stack Trace and how do you use it to debug?', options: [{ label: 'A', text: 'A performance monitoring graph; used to identify slow functions' }, { label: 'B', text: 'A list of function calls in the execution path at the point an error occurred; read from bottom (entry point) to top (error location)' }, { label: 'C', text: 'A list of all network requests made by the application' }, { label: 'D', text: 'A visualization of the call stack before the program starts' }], correct: 'B', explanation: 'A stack trace shows the chain of function calls leading to an error. Read from top (where the error occurred) or bottom (entry point) to trace execution flow. The top of the trace is usually where the fix is needed.', difficulty: 'easy', tags: ['debugging', 'stack-trace'] },
    { question: 'What is the difference between an exception and an error in most programming languages?', options: [{ label: 'A', text: 'Exceptions are compile-time; errors are runtime' }, { label: 'B', text: 'Errors are serious system-level problems (e.g., OutOfMemoryError); exceptions are recoverable application-level conditions' }, { label: 'C', text: 'Exceptions are in JavaScript; errors are in Java' }, { label: 'D', text: 'There is no difference — the terms are interchangeable' }], correct: 'B', explanation: 'In Java, Error represents unrecoverable JVM issues (OOM); Exception represents recoverable conditions. In JS/Python, the distinction is less rigid but conceptually: handle exceptions (bad input), do not try to recover from errors (process crash).', difficulty: 'medium', tags: ['exception-handling', 'error-types'] },
    { question: 'What is the best practice for logging sensitive information?', options: [{ label: 'A', text: 'Log everything for maximum debugging capability, including passwords and tokens' }, { label: 'B', text: 'Never log passwords, tokens, PII, or financial data; mask or exclude sensitive fields' }, { label: 'C', text: 'Encrypt log files so sensitive data is safe inside logs' }, { label: 'D', text: 'Only log sensitive data in development, not production' }], correct: 'B', explanation: 'Logs are often stored in log aggregation services, monitored by many people, and can be breached. Never log passwords, API keys, credit card numbers, SSNs, or personal identifiers. Mask or redact them.', difficulty: 'medium', tags: ['security', 'logging'] },
    { question: 'What is "rubber duck debugging"?', options: [{ label: 'A', text: 'Using a rubber duck keyboard for mechanical feedback while typing' }, { label: 'B', text: 'Explaining your code line-by-line to a rubber duck (or anyone) to identify logic errors through verbalization' }, { label: 'C', text: 'A type of fuzz testing using random inputs' }, { label: 'D', text: 'Debugging code in a bathtub (wet environment) for ESD protection' }], correct: 'B', explanation: 'Rubber duck debugging: explain your code to a rubber duck (or colleague). The act of articulating the problem forces you to think through each step, often revealing the bug before the listener responds.', difficulty: 'easy', tags: ['debugging-techniques', 'mindset'] },
    { question: 'What is a NullPointerException / Null Reference Error and how is it prevented?', options: [{ label: 'A', text: 'An error from using null in math operations; prevented by using zero instead of null' }, { label: 'B', text: 'Attempting to access a property or method on a null/undefined value; prevented by null checks, optional chaining, or null objects' }, { label: 'C', text: 'A memory leak caused by unreferenced objects' }, { label: 'D', text: 'An error in pointer arithmetic in C; prevented by using Java instead' }], correct: 'B', explanation: 'Null reference errors are among the most common bugs. Prevention: validate inputs, use optional chaining (?.), null object pattern, or use languages/types that make null explicit (Optional in Java, ? in TypeScript).', difficulty: 'medium', tags: ['null-handling', 'defensive-coding'] },
    { question: 'What is the purpose of a debugger and when should you use it over print statements?', options: [{ label: 'A', text: 'A spell-checker for code; use it instead of print for grammar errors' }, { label: 'B', text: 'A tool to step through code execution, inspect variables, and evaluate expressions; use for complex logic where print statements are insufficient' }, { label: 'C', text: 'A performance profiler; use it to replace console.log for production' }, { label: 'D', text: 'An automated code review tool; use it instead of peer review' }], correct: 'B', explanation: 'Debuggers (browser DevTools, VS Code, PDB) let you set breakpoints, step through code, inspect all variables in scope, and evaluate expressions. More powerful than print statements for tracing complex logic flows.', difficulty: 'medium', tags: ['debugging-tools', 'devtools'] },
    { question: 'What is an infinite loop and how do you identify one?', options: [{ label: 'A', text: 'A loop that runs more than 100 times; identified by a loop counter' }, { label: 'B', text: 'A loop whose exit condition is never met; identified by CPU usage spike, unresponsive program, and never-completing execution' }, { label: 'C', text: 'A recursive function with more than 10 levels; identified by stack overflow error' }, { label: 'D', text: 'A loop that processes infinite data streams; expected behavior for servers' }], correct: 'B', explanation: 'Infinite loops occur when the exit condition is never true (e.g., off-by-one error, condition never changes). Symptoms: 100% CPU, app freezes, no output. Fix: ensure loop variables are modified and exit conditions are reachable.', difficulty: 'easy', tags: ['loops', 'debugging'] },
    { question: 'What is the importance of error context in exception messages?', options: [{ label: 'A', text: 'Context makes error messages longer, which is always better' }, { label: 'B', text: 'Including relevant data (user ID, file path, input value) in error messages makes debugging dramatically faster' }, { label: 'C', text: 'Error context is only needed for senior developers' }, { label: 'D', text: 'Context does not matter; stack traces provide all needed information' }], correct: 'B', explanation: '"Error" is useless. "Failed to save user: userId=42, email=user@example.com, reason=unique constraint violation on email" is actionable. Always include relevant context that helps diagnose the problem without reading code.', difficulty: 'medium', tags: ['error-messages', 'debugging'] },
    { question: 'What is logging level and why does using DEBUG in production cause problems?', options: [{ label: 'A', text: 'Logging levels are only for color coding; DEBUG is too colorful for production' }, { label: 'B', text: 'Logging levels filter message verbosity; DEBUG generates massive log volume in production, causing storage costs and masking critical errors' }, { label: 'C', text: 'DEBUG level only works in development environments by design' }, { label: 'D', text: 'DEBUG logging causes application crashes in production' }], correct: 'B', explanation: 'Log levels (DEBUG, INFO, WARN, ERROR, FATAL) control verbosity. DEBUG logs everything (including loop iterations, every HTTP request). In production, use INFO/WARN/ERROR — debug logging creates noise, storage costs, and buries important alerts.', difficulty: 'medium', tags: ['logging', 'production'] },
    { question: 'What is a memory leak and how do you detect one?', options: [{ label: 'A', text: 'When code is accidentally made public (leaked); detected by code review' }, { label: 'B', text: 'When allocated memory is never freed, causing progressive memory growth; detected by profilers, heap snapshots, and memory monitoring' }, { label: 'C', text: 'When RAM physically leaks water; detected by hardware inspection' }, { label: 'D', text: 'When sensitive data is stored in memory; detected by security scans' }], correct: 'B', explanation: 'Memory leaks occur when memory is allocated but never freed (e.g., event listeners not removed, growing collections). The app uses more RAM over time until it crashes. Detect with Chrome DevTools heap snapshots, Node.js --inspect, or profilers.', difficulty: 'hard', tags: ['memory-management', 'performance'] },
    { question: 'What is the "Fail Fast" principle?', options: [{ label: 'A', text: 'Making the application crash as fast as possible for performance' }, { label: 'B', text: 'Detecting and reporting errors immediately when they occur, rather than propagating invalid state through the system' }, { label: 'C', text: 'Deploying bug fixes to production as fast as possible' }, { label: 'D', text: 'Running fast iterations in an Agile sprint' }], correct: 'B', explanation: 'Fail fast means detecting errors early (input validation, precondition checks) and stopping immediately with a clear error. This prevents corrupted state from propagating through the system, making bugs easier to find and fix.', difficulty: 'hard', tags: ['design-principles', 'error-handling'] },
    { question: 'What does "defensive programming" mean?', options: [{ label: 'A', text: 'Writing code that defends against competitors copying your algorithm' }, { label: 'B', text: 'Writing code that anticipates invalid inputs, unexpected states, and failure scenarios and handles them gracefully' }, { label: 'C', text: 'Adding comments to code to defend design decisions during code review' }, { label: 'D', text: 'Using firewalls around the application server' }], correct: 'B', explanation: 'Defensive programming assumes inputs can be wrong, dependencies can fail, and edge cases will occur. It includes null checks, input validation, guard clauses, and graceful error handling — rather than assuming everything works.', difficulty: 'medium', tags: ['defensive-coding', 'best-practices'] },
  ],

  'software-architecture': [
    { question: 'What does the "S" in SOLID stand for and what does it mean?', options: [{ label: 'A', text: 'Scalability; a class should be horizontally scalable' }, { label: 'B', text: 'Single Responsibility Principle; a class should have only one reason to change' }, { label: 'C', text: 'Separation; all components must be separate files' }, { label: 'D', text: 'Synchronization; all threads must synchronize access' }], correct: 'B', explanation: 'SRP: each class should have one, and only one, reason to change. A class that handles both user authentication AND email sending violates SRP — changes to email logic can accidentally break authentication.', difficulty: 'medium', tags: ['solid', 'oop'] },
    { question: 'What is tight coupling and why is it problematic?', options: [{ label: 'A', text: 'When code is tightly indented for readability; problematic for version control' }, { label: 'B', text: 'When components depend directly on concrete implementations; changes in one require changes in all dependents' }, { label: 'C', text: 'When two developers work on the same file simultaneously' }, { label: 'D', text: 'When a function has many parameters; problematic for readability' }], correct: 'B', explanation: 'Tight coupling means components know too much about each other. Changing one class forces changes in many others. Solution: depend on abstractions (interfaces), use dependency injection, and follow the Dependency Inversion Principle.', difficulty: 'medium', tags: ['coupling', 'solid'] },
    { question: 'What is the Dependency Injection (DI) pattern?', options: [{ label: 'A', text: 'A technique for injecting malicious dependencies into third-party packages' }, { label: 'B', text: 'Providing dependencies to a class from outside rather than having the class create them internally' }, { label: 'C', text: 'Automatically installing missing npm packages at runtime' }, { label: 'D', text: 'A technique for injecting SQL into database queries' }], correct: 'B', explanation: 'DI: instead of a class creating its own database connection, it receives one from outside. This makes the class testable (inject a mock), flexible (swap implementations), and loosely coupled to specific implementations.', difficulty: 'medium', tags: ['dependency-injection', 'patterns'] },
    { question: 'What is a Microservices architecture and what is its main trade-off?', options: [{ label: 'A', text: 'Small code files; trade-off is too many files to manage' }, { label: 'B', text: 'Decomposing an application into small, independent services; trade-off is distributed systems complexity (network failures, latency, data consistency)' }, { label: 'C', text: 'Using micro-frameworks instead of large ones; trade-off is less documentation' }, { label: 'D', text: 'A mobile-first architecture; trade-off is poor desktop support' }], correct: 'B', explanation: 'Microservices offer independent deployability and scaling per service. However, you trade simplicity for distributed systems problems: network partitions, service discovery, distributed tracing, and eventual consistency.', difficulty: 'hard', tags: ['microservices', 'architecture'] },
    { question: 'What is the Observer Pattern?', options: [{ label: 'A', text: 'A pattern where a manager observes developer productivity' }, { label: 'B', text: 'A pattern where an object (subject) notifies a list of dependents (observers) about state changes' }, { label: 'C', text: 'A logging pattern that observes all function calls' }, { label: 'D', text: 'A security pattern for monitoring user behavior' }], correct: 'B', explanation: 'Observer (pub/sub) decouples event producers from consumers. The subject maintains a list of observers and notifies all on state change. Used in event systems, GUI frameworks, and reactive programming (Observables in RxJS).', difficulty: 'medium', tags: ['design-patterns', 'observer'] },
    { question: 'What is the difference between Monolithic and Microservices architecture?', options: [{ label: 'A', text: 'Monolithic uses one programming language; microservices use many' }, { label: 'B', text: 'Monolithic: all components in one deployable unit; Microservices: independent services deployed separately' }, { label: 'C', text: 'Monolithic is older and always worse; microservices are modern and always better' }, { label: 'D', text: 'Monolithic uses SQL; microservices use NoSQL' }], correct: 'B', explanation: 'Monolith: simpler to develop, test, and debug but harder to scale individual components. Microservices: independent deployment and scaling but complex to manage. Start monolith, extract services when needed.', difficulty: 'medium', tags: ['architecture-patterns'] },
    { question: 'What is the Facade Pattern?', options: [{ label: 'A', text: 'A pattern that hides bugs behind a clean interface' }, { label: 'B', text: 'A simplified interface to a complex subsystem, making it easier to use' }, { label: 'C', text: 'The visual layer of an application (the facade)' }, { label: 'D', text: 'A pattern for creating fake objects in tests' }], correct: 'B', explanation: 'Facade provides a simple interface to a complex system. Example: a PaymentFacade that simplifies calling multiple payment gateway classes, currency conversion, fraud detection, and receipt generation behind one simple charge() method.', difficulty: 'medium', tags: ['design-patterns', 'facade'] },
    { question: 'What is Event-Driven Architecture?', options: [{ label: 'A', text: 'An architecture driven by user interface events only' }, { label: 'B', text: 'Components communicate by producing and consuming events asynchronously, enabling loose coupling' }, { label: 'C', text: 'An architecture where only event-related features are built' }, { label: 'D', text: 'Using JavaScript event listeners as the sole communication mechanism' }], correct: 'B', explanation: 'EDA: services emit events (user.registered, order.placed) and other services react. This decouples producers from consumers. Used in Kafka, RabbitMQ, AWS EventBridge for scalable, loosely-coupled systems.', difficulty: 'hard', tags: ['event-driven', 'architecture'] },
    { question: 'What is the Repository Pattern?', options: [{ label: 'A', text: 'A pattern for organizing Git repositories' }, { label: 'B', text: 'An abstraction layer between business logic and data access, allowing swappable data sources' }, { label: 'C', text: 'A pattern for storing design documents' }, { label: 'D', text: 'A centralized pattern for managing npm packages' }], correct: 'B', explanation: 'Repository pattern abstracts data persistence. Business logic calls UserRepository.findById() without knowing if data comes from SQL, MongoDB, or an API. This enables testing with in-memory repositories and swapping databases easily.', difficulty: 'hard', tags: ['repository-pattern', 'clean-architecture'] },
    { question: 'What is "Separation of Concerns" (SoC)?', options: [{ label: 'A', text: 'Separating the development team into different floors of an office' }, { label: 'B', text: 'Organizing code so each section addresses a single distinct concern, reducing coupling between unrelated functionality' }, { label: 'C', text: 'Documenting concerns raised in code review separately' }, { label: 'D', text: 'Using separate programming languages for frontend and backend' }], correct: 'B', explanation: 'SoC: keep database logic out of UI components, keep business rules out of data access layers. MVC is a classic SoC pattern — Model (data), View (display), Controller (logic) each have a single concern.', difficulty: 'medium', tags: ['design-principles', 'architecture'] },
    { question: 'What is the Singleton Pattern and what is the criticism against it?', options: [{ label: 'A', text: 'A class with one method; criticism: too simple' }, { label: 'B', text: 'Ensures only one instance of a class exists; criticism: global state makes testing difficult, violates SRP, creates hidden dependencies' }, { label: 'C', text: 'A pattern for unmarried developers; no real criticism' }, { label: 'D', text: 'A pattern that uses a single function for all logic; criticism: violates DRY' }], correct: 'B', explanation: 'Singleton restricts instantiation to one object. While useful (logging, config), it is often criticized as a disguised global variable — it creates hidden dependencies, makes unit testing difficult, and can cause race conditions.', difficulty: 'hard', tags: ['design-patterns', 'singleton'] },
    { question: 'What is Clean Architecture?', options: [{ label: 'A', text: 'Code with no code comments or dead code' }, { label: 'B', text: 'An architectural approach organizing code into concentric circles (layers) where outer layers depend on inner ones, not vice versa' }, { label: 'C', text: 'A CI/CD pipeline that keeps the codebase clean of unused branches' }, { label: 'D', text: 'An architecture that uses only functional programming' }], correct: 'B', explanation: 'Clean Architecture (Uncle Bob) organizes code into layers: Entities (core business), Use Cases (application logic), Interface Adapters (controllers, gateways), Frameworks (web, DB). Dependencies only point inward — business logic is independent of frameworks.', difficulty: 'hard', tags: ['clean-architecture', 'solid'] },
    { question: 'What does YAGNI stand for and how does it prevent over-engineering?', options: [{ label: 'A', text: '"You Always Get New Ideas"; encourages constant feature addition' }, { label: 'B', text: '"You Aren\'t Gonna Need It"; discourages building features before they are actually needed' }, { label: 'C', text: '"Your API Generally Needs Interfaces"; encourages interface-first design' }, { label: 'D', text: '"Your Application Gets Naturally Improved"; describes organic code growth' }], correct: 'B', explanation: "YAGNI: don't build features speculatively. If the requirement does not exist today, do not code for it — requirements change, and that code may never be used while adding complexity to maintain.", difficulty: 'medium', tags: ['design-principles', 'agile'] },
    { question: 'What is the Strategy Pattern?', options: [{ label: 'A', text: 'A business plan for software product launch' }, { label: 'B', text: 'Defines a family of algorithms, encapsulates each one, and makes them interchangeable at runtime' }, { label: 'C', text: 'A pattern for strategic caching of database results' }, { label: 'D', text: 'A project management strategy for coding teams' }], correct: 'B', explanation: 'Strategy lets you select an algorithm at runtime. Example: a payment processor that can swap between PayPalStrategy, StripeStrategy, or CryptoStrategy without changing the calling code. Follows Open/Closed Principle.', difficulty: 'hard', tags: ['design-patterns', 'strategy'] },
    { question: 'What is Technical Debt?', options: [{ label: 'A', text: 'Money owed to software vendors for license fees' }, { label: 'B', text: 'The implied cost of rework caused by choosing quick, expedient solutions over better approaches' }, { label: 'C', text: 'The amount of code written by the technical team' }, { label: 'D', text: 'Infrastructure costs for cloud services' }], correct: 'B', explanation: 'Technical debt accumulates when you take shortcuts (hacky fixes, skipping tests, poor design) to ship faster. Like financial debt, it accrues "interest" — future development gets slower and harder until the debt is repaid through refactoring.', difficulty: 'medium', tags: ['technical-debt', 'refactoring'] },
  ],

  'agile-management': [
    { question: 'What is Scope Creep and how does it harm software projects?', options: [{ label: 'A', text: 'When code files become too large' }, { label: 'B', text: 'Uncontrolled growth of project scope through unplanned feature additions, causing delays and budget overruns' }, { label: 'C', text: 'When developers creep into management roles' }, { label: 'D', text: 'Gradually improving code quality over time' }], correct: 'B', explanation: 'Scope creep destroys project timelines and budgets. Every added feature without time/cost adjustment pushes delivery dates. Combat it with change control processes, clear requirements, and stakeholder communication.', difficulty: 'easy', tags: ['project-management', 'agile'] },
    { question: 'What is a User Story in Agile development?', options: [{ label: 'A', text: 'A narrative written by users about their experience with the software' }, { label: 'B', text: 'A short description of a feature from the end user perspective: "As a [user], I want [feature] so that [benefit]"' }, { label: 'C', text: 'A story developers tell users about project delays' }, { label: 'D', text: 'A use-case diagram in UML format' }], correct: 'B', explanation: 'User stories capture requirements from the user\'s perspective in simple language. The format "As a [role], I want [action], so that [benefit]" keeps teams focused on user value rather than technical implementation details.', difficulty: 'easy', tags: ['agile', 'user-stories'] },
    { question: 'What is a Sprint in Scrum?', options: [{ label: 'A', text: 'A race to finish all project tasks at once' }, { label: 'B', text: 'A fixed-length time box (typically 1-4 weeks) during which a team completes a set of planned work' }, { label: 'C', text: 'Running the application to test performance' }, { label: 'D', text: 'A quick bug fix deployed immediately to production' }], correct: 'B', explanation: 'Sprints are the heartbeat of Scrum. Each sprint produces a potentially shippable increment. Fixed duration forces prioritization, creates regular rhythm, and enables frequent inspection and adaptation of the product and process.', difficulty: 'easy', tags: ['scrum', 'agile'] },
    { question: 'What is the danger of skipping documentation in software development?', options: [{ label: 'A', text: 'Documentation is optional; code is self-documenting' }, { label: 'B', text: 'Knowledge becomes locked in individuals\' heads; onboarding new developers becomes very slow; system becomes a black box' }, { label: 'C', text: 'Documentation files take up too much disk space' }, { label: 'D', text: 'Documentation slows down version control operations' }], correct: 'B', explanation: 'No documentation leads to tribal knowledge — key system understanding lives only with senior developers. When they leave, the knowledge leaves too. New developers take months to onboard. Document architecture, APIs, and non-obvious decisions.', difficulty: 'medium', tags: ['documentation', 'knowledge-management'] },
    { question: 'What is a Daily Standup in Agile and what are the three key questions?', options: [{ label: 'A', text: 'A daily performance review; questions: what did you earn, what will you earn, and how long did it take?' }, { label: 'B', text: 'A short daily sync (≤15 min); questions: What did I do yesterday? What will I do today? Are there any blockers?' }, { label: 'C', text: 'A daily planning session; questions: What is the sprint goal, who does what, when is it due?' }, { label: 'D', text: 'A team meeting requiring everyone to stand; questions are not standardized' }], correct: 'B', explanation: 'Standups keep teams synchronized with minimal time investment. The three questions ensure everyone knows the plan, progress, and impediments. It is NOT a status report to management — it is for the team.', difficulty: 'easy', tags: ['scrum', 'standup'] },
    { question: 'What is the risk of not doing a code review?', options: [{ label: 'A', text: 'Code reviews are only needed for junior developers' }, { label: 'B', text: 'Bugs, security issues, poor design, and knowledge silos go undetected — one developer alone misses things' }, { label: 'C', text: 'Code is slightly slower without reviews' }, { label: 'D', text: 'It violates the software license agreement' }], correct: 'B', explanation: 'Code reviews catch bugs, security vulnerabilities, design issues, and spread knowledge across the team. Studies show reviews find 60-70% of defects before testing. Skipping them leads to expensive bugs in production.', difficulty: 'easy', tags: ['code-review', 'quality'] },
    { question: 'What is Velocity in Agile and how can it be misused?', options: [{ label: 'A', text: 'The speed of the CI/CD pipeline; misused by slowing it down artificially' }, { label: 'B', text: 'The amount of work completed per sprint; misused when teams inflate estimates or game the metric for management pressure' }, { label: 'C', text: 'The typing speed of developers; misused as a productivity metric' }, { label: 'D', text: 'The number of features shipped per quarter; misused by comparing different teams' }], correct: 'B', explanation: 'Velocity measures story points per sprint for sprint planning. Misuse: treating it as a productivity metric or comparing teams, causing teams to inflate estimates just to show "high velocity" rather than delivering real value.', difficulty: 'hard', tags: ['agile-metrics', 'scrum'] },
    { question: 'What is the Definition of Done (DoD) in Scrum?', options: [{ label: 'A', text: 'When a developer thinks their code is finished' }, { label: 'B', text: 'A shared checklist of criteria that must be met before a story is considered complete (coded, tested, reviewed, documented, deployed)' }, { label: 'C', text: 'When the project manager signs off on a feature' }, { label: 'D', text: 'The last day of the project' }], correct: 'B', explanation: 'DoD ensures shared understanding of "done." Without it, "done" means different things to different people. A robust DoD includes: unit tests written, code reviewed, integration tests pass, documentation updated, and deployed to staging.', difficulty: 'medium', tags: ['scrum', 'quality'] },
    { question: 'What is a Retrospective in Agile?', options: [{ label: 'A', text: 'Looking back at competitor products for inspiration' }, { label: 'B', text: 'A meeting at the end of each sprint where the team reflects on what went well, what did not, and what to improve' }, { label: 'C', text: 'Reviewing old code that was written years ago' }, { label: 'D', text: 'A performance review of individual developers' }], correct: 'B', explanation: 'Retrospectives drive continuous improvement. The team honestly discusses process, collaboration, and tools — not products. Common format: What went well? What did not? What will we do differently? Action items must be specific and followed through.', difficulty: 'easy', tags: ['retrospective', 'continuous-improvement'] },
    { question: 'What is the risk of "Gold Plating" in software development?', options: [{ label: 'A', text: 'Using too many premium third-party libraries' }, { label: 'B', text: 'Adding extra features or quality beyond what is required, wasting time and potentially complicating the product' }, { label: 'C', text: 'Using gold-colored UI themes' }, { label: 'D', text: 'Over-documenting code' }], correct: 'B', explanation: 'Gold plating means adding unnecessary features or polish that the customer did not ask for. Developers spend time on features that may not be valued, delaying required features and potentially confusing users with added complexity.', difficulty: 'medium', tags: ['scope', 'agile-principles'] },
    { question: 'What is a Product Backlog?', options: [{ label: 'A', text: 'A list of bugs to fix' }, { label: 'B', text: 'An ordered list of all features, fixes, and work items for the product, managed by the Product Owner' }, { label: 'C', text: 'The queue of code waiting to be deployed' }, { label: 'D', text: 'A list of archived completed features' }], correct: 'B', explanation: 'The Product Backlog is the single source of truth for all planned work. The Product Owner prioritizes it by value, risk, and dependencies. The team pulls from the top for each sprint — the backlog is never fully depleted.', difficulty: 'easy', tags: ['scrum', 'backlog'] },
    { question: 'What is "Technical Backlog" vs "Product Backlog"?', options: [{ label: 'A', text: 'They are the same thing' }, { label: 'B', text: 'Technical backlog contains infrastructure, refactoring, and debt items; product backlog contains user-facing features' }, { label: 'C', text: 'Technical backlog is for backend work; product backlog is for frontend work' }, { label: 'D', text: 'Technical backlog is prioritized by developers; product backlog by end-users' }], correct: 'B', explanation: 'Technical backlog tracks internal quality improvements: refactoring, infrastructure upgrades, test coverage improvements, and security fixes. Balancing both backlogs ensures the product delivers value without accumulating unsustainable technical debt.', difficulty: 'medium', tags: ['backlog', 'technical-debt'] },
    { question: 'What is Kanban and how does it differ from Scrum?', options: [{ label: 'A', text: 'A Japanese food; it differs from Scrum in calorie count' }, { label: 'B', text: 'A flow-based method using visual boards with WIP limits; unlike Scrum, it has no fixed sprints or roles' }, { label: 'C', text: 'A programming methodology; it differs from Scrum in programming language' }, { label: 'D', text: 'An enterprise project management tool; it is more expensive than Scrum' }], correct: 'B', explanation: 'Kanban focuses on continuous flow and limiting Work In Progress (WIP). No sprints, no fixed cadence. Items flow through columns (To Do → In Progress → Done). Great for maintenance teams or operations where work is unpredictable.', difficulty: 'medium', tags: ['kanban', 'agile-methods'] },
    { question: 'What is Continuous Integration (CI) and why is it an Agile best practice?', options: [{ label: 'A', text: 'Integrating developer salaries continuously throughout the month' }, { label: 'B', text: 'Automatically building and testing code with every commit, catching integration problems early' }, { label: 'C', text: 'Deploying code to production continuously without testing' }, { label: 'D', text: 'A daily meeting where developers integrate their plans' }], correct: 'B', explanation: 'CI: every commit triggers automated build + tests. This catches integration issues within minutes rather than discovering them during final integration. The longer branches diverge, the harder integration becomes — CI keeps the main branch always releasable.', difficulty: 'easy', tags: ['ci-cd', 'agile'] },
    { question: 'What is the Minimum Viable Product (MVP) concept?', options: [{ label: 'A', text: 'The cheapest version of a product possible' }, { label: 'B', text: 'The smallest version of a product with just enough features to satisfy early users and gather validated feedback' }, { label: 'C', text: 'A product with minimum security features' }, { label: 'D', text: 'A product built with the minimum number of developers' }], correct: 'B', explanation: 'MVP is the smallest product that delivers user value and enables validated learning. Ship it early to real users, measure real behavior, and iterate. Avoids building large features nobody wants before discovering what users actually need.', difficulty: 'easy', tags: ['mvp', 'lean-startup'] },
  ],

  'devops-deployment': [
    { question: 'What is Continuous Deployment (CD) and how does it differ from Continuous Delivery?', options: [{ label: 'A', text: 'They are the same — both deploy every commit automatically to production' }, { label: 'B', text: 'Continuous Delivery: every change is releasable but deployment requires human approval; Continuous Deployment: every passing change auto-deploys to production' }, { label: 'C', text: 'Continuous Deployment is for mobile apps; Continuous Delivery is for web apps' }, { label: 'D', text: 'Continuous Delivery deploys hourly; Continuous Deployment deploys daily' }], correct: 'B', explanation: 'Continuous Delivery: code is always ready to deploy — one click to release. Continuous Deployment: no human gate — every commit that passes all tests automatically goes to production. CD requires high test confidence.', difficulty: 'medium', tags: ['ci-cd', 'deployment'] },
    { question: 'What is the danger of not having a rollback plan for deployments?', options: [{ label: 'A', text: 'Rollbacks are not needed with modern tools' }, { label: 'B', text: 'If a deployment causes production issues, you cannot revert quickly, leading to extended downtime' }, { label: 'C', text: 'It violates CI/CD best practices' }, { label: 'D', text: 'Without rollback, you lose Git history' }], correct: 'B', explanation: 'Deployments can introduce critical bugs. Without a rollback plan (blue-green deployment, feature flags, versioned containers), you are stuck debugging in production while users suffer. Always know how to revert in under 5 minutes.', difficulty: 'medium', tags: ['deployment', 'reliability'] },
    { question: 'What is a Docker container and what problem does it solve?', options: [{ label: 'A', text: 'A physical server rack; solves hardware cooling problems' }, { label: 'B', text: 'A lightweight, isolated runtime environment packaging code and dependencies; solves "works on my machine" problems' }, { label: 'C', text: 'A cloud storage service; solves backup problems' }, { label: 'D', text: 'A code editor plugin; solves syntax highlighting problems' }], correct: 'B', explanation: 'Docker containers package app + dependencies + OS libraries into a single unit. Runs identically in dev, staging, and production. Eliminates environment inconsistencies that cause "it works on my machine" failures.', difficulty: 'medium', tags: ['docker', 'containers'] },
    { question: 'What is Infrastructure as Code (IaC)?', options: [{ label: 'A', text: 'Writing code that describes the infrastructure that runs it' }, { label: 'B', text: 'Managing and provisioning infrastructure through machine-readable config files rather than manual processes' }, { label: 'C', text: 'Infrastructure that is written using low-level code like C or Assembly' }, { label: 'D', text: 'Using code comments to document server configurations' }], correct: 'B', explanation: 'IaC (Terraform, Ansible, CloudFormation) defines servers, networks, and services as code. Infrastructure becomes version-controlled, repeatable, and reviewable — eliminating snowflake servers that only one sysadmin understands.', difficulty: 'hard', tags: ['iac', 'devops'] },
    { question: 'What is the danger of having different configurations between development, staging, and production environments?', options: [{ label: 'A', text: 'Different configs are expected and have no downsides' }, { label: 'B', text: 'Bugs appear in production that cannot be reproduced in development, making them very hard to debug' }, { label: 'C', text: 'Different configurations cause slower deployment pipelines' }, { label: 'D', text: 'It increases cloud storage costs' }], correct: 'B', explanation: 'Environment parity is critical. If dev uses SQLite but prod uses PostgreSQL, bugs only appear in production. Use the same software, same OS, same configs across all environments — only differ in secrets and scale.', difficulty: 'medium', tags: ['environment-management', '12-factor'] },
    { question: 'What is Blue-Green Deployment?', options: [{ label: 'A', text: 'Deploying on blue-colored servers in cold climates and green servers in tropical ones' }, { label: 'B', text: 'Running two identical environments (blue=live, green=new version); switch traffic to green after validation, blue becomes standby' }, { label: 'C', text: 'A deployment strategy for eco-friendly datacenters' }, { label: 'D', text: 'Using two different cloud providers for redundancy' }], correct: 'B', explanation: 'Blue-green eliminates downtime: green receives the new release, is tested thoroughly, then traffic switches instantly. If problems arise, rollback = switch back to blue. Both environments are identical except the version.', difficulty: 'hard', tags: ['deployment-strategies', 'zero-downtime'] },
    { question: 'What is a health check endpoint and why should every service have one?', options: [{ label: 'A', text: 'An endpoint for medical professionals to check patient health records' }, { label: 'B', text: 'An endpoint (GET /health) that returns service status, enabling load balancers and orchestrators to detect unhealthy instances' }, { label: 'C', text: 'A monitoring tool that checks developer health metrics' }, { label: 'D', text: 'An endpoint that checks the health of the API documentation' }], correct: 'B', explanation: 'Health check endpoints (GET /health → 200 OK) tell load balancers, Kubernetes, and monitoring systems if an instance is ready to serve traffic. Without them, traffic may be routed to broken instances.', difficulty: 'medium', tags: ['reliability', 'kubernetes'] },
    { question: 'What is a CI/CD pipeline and what are its key stages?', options: [{ label: 'A', text: 'A water pipe for cooling servers; stages: intake, cooling, discharge' }, { label: 'B', text: 'Automated workflow from code commit to deployment; stages: build, test, static analysis, security scan, deploy to staging, deploy to prod' }, { label: 'C', text: 'A project management workflow; stages: plan, design, develop, test' }, { label: 'D', text: 'A network pipeline; stages: packet assembly, transmission, reception' }], correct: 'B', explanation: 'CI/CD pipeline automates the software delivery process. Each stage acts as a quality gate — if any stage fails, deployment stops. This ensures only verified, tested code reaches production.', difficulty: 'medium', tags: ['ci-cd', 'automation'] },
    { question: 'What is Kubernetes and what problem does it solve?', options: [{ label: 'A', text: 'A programming language for distributed systems' }, { label: 'B', text: 'A container orchestration platform that automates deployment, scaling, self-healing, and management of containerized applications' }, { label: 'C', text: 'A version control system for infrastructure code' }, { label: 'D', text: 'A monitoring tool for distributed databases' }], correct: 'B', explanation: 'Kubernetes (K8s) manages containerized apps at scale: auto-scaling, rolling updates, self-healing (restarts crashed containers), service discovery, and load balancing — eliminating manual server management complexity.', difficulty: 'hard', tags: ['kubernetes', 'orchestration'] },
    { question: 'What is the 12-Factor App methodology?', options: [{ label: 'A', text: 'An app that has exactly 12 features' }, { label: 'B', text: 'A set of 12 best practices for building scalable, maintainable, cloud-native web applications' }, { label: 'C', text: 'A development methodology requiring 12 developers per team' }, { label: 'D', text: 'An app deployment checklist with 12 steps' }], correct: 'B', explanation: '12-Factor (Heroku) covers: codebase, dependencies, config (env vars), backing services, build/release/run, processes, port binding, concurrency, disposability, dev/prod parity, logs as streams, admin processes — creating cloud-native, scalable apps.', difficulty: 'hard', tags: ['cloud-native', '12-factor'] },
    { question: 'What is the danger of hardcoding environment-specific values in application code?', options: [{ label: 'A', text: 'Hardcoded values are actually recommended for simplicity' }, { label: 'B', text: 'The code must be changed and redeployed for every environment, and secrets are exposed in the codebase' }, { label: 'C', text: 'Hardcoded values cause compilation errors' }, { label: 'D', text: 'It makes the code run slower' }], correct: 'B', explanation: 'Hardcoding database URLs, API keys, or environment names forces code changes per environment and exposes secrets in version control. Use environment variables (12-Factor principle) to separate config from code.', difficulty: 'easy', tags: ['configuration', 'security'] },
    { question: 'What is observability in DevOps (Metrics, Logs, Traces)?', options: [{ label: 'A', text: 'Having a manager watch developers code in real-time' }, { label: 'B', text: 'The ability to understand internal system state from external outputs — metrics (what), logs (why), and distributed traces (where/how)' }, { label: 'C', text: 'Watching server CPU usage on a dashboard' }, { label: 'D', text: 'Code review observation by senior developers' }], correct: 'B', explanation: 'Observability (3 pillars): Metrics (Prometheus) — quantitative measurements; Logs (ELK) — discrete events; Traces (Jaeger) — request flows through services. Together they answer "why is production broken?" quickly.', difficulty: 'hard', tags: ['observability', 'monitoring'] },
    { question: 'What is a Feature Flag (Feature Toggle)?', options: [{ label: 'A', text: 'A national flag on the feature list of an international product' }, { label: 'B', text: 'A configuration switch that enables or disables features without deploying new code' }, { label: 'C', text: 'A Git branch naming convention for new features' }, { label: 'D', text: 'A UI component that flags important features to users' }], correct: 'B', explanation: 'Feature flags decouple deployment from release. Deploy new code with the feature disabled, then enable it gradually (10% → 50% → 100% of users). Enables A/B testing, canary releases, and instant rollback without redeployment.', difficulty: 'medium', tags: ['feature-flags', 'deployment'] },
    { question: 'What is the problem with long deployment pipelines (taking hours)?', options: [{ label: 'A', text: 'Long pipelines use more electricity' }, { label: 'B', text: 'Developers wait hours for feedback, slowing development velocity and making multiple deploys per day impossible' }, { label: 'C', text: 'Long pipelines are only a problem for small teams' }, { label: 'D', text: 'They cause the CI server to overheat' }], correct: 'B', explanation: 'A pipeline taking 2 hours means 2-hour feedback loops on bugs. Developers context-switch, lose flow, and cannot iterate quickly. Optimize pipelines: parallelize tests, cache dependencies, run fast tests first, defer slow E2E tests.', difficulty: 'medium', tags: ['ci-cd', 'performance'] },
    { question: 'What is a Secret Manager and why is it better than .env files in production?', options: [{ label: 'A', text: 'A person who manages company secrets; better because humans are more reliable' }, { label: 'B', text: 'A service (AWS Secrets Manager, HashiCorp Vault) that securely stores, rotates, and audits access to secrets — more secure, auditable, and rotatable than static .env files' }, { label: 'C', text: 'A .gitignore extension that manages .env files; same security level' }, { label: 'D', text: 'An encrypted USB drive for storing API keys; better because it is offline' }], correct: 'B', explanation: 'Secret managers provide: access auditing, automatic rotation, fine-grained IAM permissions, encryption at rest, and no static files to accidentally expose. Production secrets should never live in files on disk.', difficulty: 'hard', tags: ['secrets-management', 'security'] },
  ],
};

async function seed() {
  try {
    await mongoose.connect("mongodb://localhost:27017/softwarequiz");
    console.log('✅ Connected to MongoDB');

    // Clear existing data
    await Category.deleteMany({});
    await Question.deleteMany({});
    console.log('🗑️  Cleared existing data');

    // Insert categories
    const insertedCategories = await Category.insertMany(categories);
    console.log(`📂 Inserted ${insertedCategories.length} categories`);

    // Build slug → ID map
    const slugToId = {};
    insertedCategories.forEach((cat) => {
      slugToId[cat.slug] = cat._id;
    });

    // Insert questions
    let totalQuestions = 0;
    for (const [slug, questions] of Object.entries(questionBank)) {
      const categoryId = slugToId[slug];
      if (!categoryId) {
        console.warn(`⚠️  No category found for slug: ${slug}`);
        continue;
      }
      const questionsWithCategory = questions.map((q) => ({ ...q, categoryId }));
      await Question.insertMany(questionsWithCategory);
      totalQuestions += questions.length;
      console.log(`  ✅ ${slug}: ${questions.length} questions`);
    }

    console.log(`\n🎉 Seed complete! ${insertedCategories.length} categories, ${totalQuestions} questions inserted.`);
    process.exit(0);
  } catch (err) {
    console.error('❌ Seed error:', err);
    process.exit(1);
  }
}

seed();
